def inspect_records(mapping):
    if 'records' not in mapping:
        return {'ok': False, 'records': []}
    records = mapping['records']
    if records is None:
        return {'ok': False, 'records': []}
    if not (type(records) is list and 1 <= len(records) <= 2):
        return {'ok': False, 'records': []}
    ok = True
    for record in records:
        if type(record) is not dict or set(record) != {'code', 'enabled'}:
            ok = False
            break
        if not (type(record['code']) is str and 2 <= len(record['code']) <= 5 and type(record['enabled']) is bool):
            ok = False
            break
    return {'ok': ok, 'records': records if ok else []}
